import random

GROUP = "algebra"
SKILL = "induction"


def find_max_polynomial_sum(degree, min_degree, max_degree):
    if degree == 0:
        return 0

    if degree < min_degree:
        return -1

    max_sum = 0

    for d in range(min_degree, max_degree + 1):
        if d <= degree:
            remaining_degree = degree - d
            count = find_max_polynomial_sum(remaining_degree, min_degree, d - 1)

            if count != -1:
                max_sum = max(max_sum, count + 1)

    return max_sum


def generate(seed):
    rng = random.Random(seed)

    min_degree = rng.randint(1, 3)
    max_degree = rng.randint(3, 7)
    degree = rng.randint(1000, 5000)

    answer = find_max_polynomial_sum(degree, min_degree, max_degree)

    check = -1
    for d in range(min_degree, max_degree + 1):
        if d <= degree:
            remaining_degree = degree - d
            count = find_max_polynomial_sum(remaining_degree, min_degree, d - 1)
            if count != -1:
                check = max(check, 1 + count)

    assert answer == check, f"answer={answer} check={check}"

    problem = (
        f"Consider polynomials of degree from {min_degree} to {max_degree} (inclusive). "
        f"What is the maximum number of distinct polynomials that can be selected such that no polynomial exceeds the total degree {degree} and the sum of their degrees is exactly {degree}? State only the integer."
    )
    return problem, str(answer)
